const INVENTORY_MAX=50;
const itemInfo={wood:{name:'Planks',desc:'Building material',weight:1},scrap:{name:'Scrap',desc:'Metal salvage',weight:1},cloth:{name:'Cloth',desc:'Bandage material',weight:1},parts:{name:'Parts',desc:'Mechanical salvage',weight:1},ammo:{name:'Ammo',desc:'Makeshift rounds',weight:.5},food:{name:'Food',desc:'Restores 30 hunger',weight:1},chem:{name:'Chem',desc:'Restores 25 health',weight:1},fuel:{name:'Fuel',desc:'Vehicle fuel',weight:2}};
function inventoryUsed(){return Object.entries(resources).reduce((n,[k,v])=>n+(Number(v)||0)*(itemInfo[k]?.weight||1),0)}
function canCarry(extra=1){return inventoryUsed()+extra<=INVENTORY_MAX}
function updateInventory(){const names={wood:'Planks',scrap:'Scrap',cloth:'Cloth',parts:'Parts',ammo:'Ammo',food:'Food',chem:'Chem',fuel:'Fuel'};$('items').innerHTML=Object.entries(resources).map(([k,v])=>`<div class="item"><span>${names[k]}</span><span>${v}</span></div>`).join('');const used=inventoryUsed(),pct=clamp(used/INVENTORY_MAX*100,0,100);$('capacity').innerHTML=`<div class="capacity"><span>${Math.round(used)}/${INVENTORY_MAX}</span><div class="capacity-track"><div class="capacity-fill" style="width:${pct}%"></div></div></div>`;if($('inventoryModal')?.classList.contains('open'))renderInventory()}

