-function renderRecipes(){$('recipes').innerHTML=recipes.map(r=>{let ok=Object.entries(r.cost).every(([k,v])=>resources[k]>=v);return `<div class="recipe"><div><strong>${r.name}</strong><small>${r.desc}<br>NEEDS ${Object.entries(r.cost).map(([k,v])=>`${v} ${k.toUpperCase()}`).join(' · ')}</small></div><button data-recipe="${r.id}" ${ok?'':'disabled'}>${ok?'CRAFT':'MISSING'}</button></div>`}).join('');$('recipes').querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>{const r=recipes.find(x=>x.id===b.dataset.recipe);if(!Object.entries(r.cost).every(([k,v])=>resources[k]>=v))return;for(const[k,v]of Object.entries(r.cost))resources[k]-=v;r.do();updateInventory();renderRecipes()})}
+function renderRecipes(){$('recipes').innerHTML=recipes.map(r=>{let ok=Object.entries(r.cost).every(([k,v])=>resources[k]>=v);return `<div class="recipe"><div><strong>${r.name}</strong><small>${r.desc}<br>NEEDS ${Object.entries(r.cost).map(([k,v])=>`${v} ${k.toUpperCase()}`).join(' · ')}</small></div><button data-recipe="${r.id}" ${ok?'':'disabled'}>${ok?'CRAFT':'MISSING'}</button></div>`}).join('');$('recipes').querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>{const r=recipes.find(x=>x.id===b.dataset.recipe);if(!Object.entries(r.cost).every(([k,v])=>resources[k]>=v))return;if(r.id==='ammo'&&!canCarry(2)){showToast('Inventory full. Leave 2 carry weight for ammo.');return}for(const[k,v]of Object.entries(r.cost))resources[k]-=v;r.do();updateInventory();renderRecipes();saveGame()})}
 function openCraft(){renderRecipes();openModal('craftModal')}
 function renderInventory(){const used=inventoryUsed(),pct=clamp(used/INVENTORY_MAX*100,0,100);$('inventoryCapacity').innerHTML=`<div class="capacity"><span>CARRY WEIGHT ${Math.round(used)} / ${INVENTORY_MAX}</span><div class="capacity-track"><div class="capacity-fill" style="width:${pct}%"></div></div></div>`;$('equippedWeapon').textContent=weapon==='shiv'?'Scrap shiv':weapon==='bat'?'Nailed bat':weapon==='pistol'?'Repaired sidearm':'Fists';$('inventoryGrid').innerHTML=Object.entries(resources).map(([k,v])=>{const info=itemInfo[k],usable=k==='food'||k==='chem';return `<div class="inv-card"><div><strong>${info.name}</strong> <em>×${v}</em><br><small>${info.desc}<br>${info.weight} wt / unit</small></div><button data-use="${k}" ${usable&&v>0?'':'disabled'}>${k==='food'?'EAT':k==='chem'?'USE':'STORAGE'}</button></div>`}).join('');$('inventoryGrid').querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>useInventoryItem(b.dataset.use))}
 function openInventory(){renderInventory();openModal('inventoryModal')}
 function useInventoryItem(k){if(k==='food'){if(resources.food<=0)return;if(player.hunger>=100&&player.hp>=100){showToast('No need to eat yet.');return}resources.food--;player.hunger=Math.min(100,player.hunger+30);player.hp=Math.min(100,player.hp+5);showToast('Ate food · hunger restored.') }else if(k==='chem'){if(resources.chem<=0)return;if(player.hp>=100){showToast('Health is already full.');return}resources.chem--;player.hp=Math.min(100,player.hp+25);showToast('Used chemicals · +25 health.') }else return;updateInventory();updateHud();saveGame()}

